from typing import List

def criticalConnections(V: int, adj: List[List[int]]) -> List[List[int]]:
    def dfs(node, parent, low, disc, time, stack, visited, result):
        nonlocal timer
        visited[node] = True
        low[node] = disc[node] = timer
        timer += 1
        stack.append(node)

        for neighbor in adj[node]:
            if neighbor == parent:
                continue
            if not visited[neighbor]:
                dfs(neighbor, node, low, disc, time, stack, visited, result)
                low[node] = min(low[node], low[neighbor])

                if low[neighbor] > disc[node]:
                    result.append(sorted((node, neighbor)))
            else:
                low[node] = min(low[node], disc[neighbor])

        if low[node] == disc[node]:
            while stack[-1] != node:
                stack.pop()
            stack.pop()

    timer = 0
    low = [float('inf')] * V
    disc = [float('inf')] * V
    visited = [False] * V
    stack = []
    result = []

    for i in range(V):
        if not visited[i]:
            dfs(i, -1, low, disc, timer, stack, visited, result)

    return result
